import type { ColumnDef } from "@tanstack/vue-table";
import { ArrowUpDown } from "lucide-vue-next";
import { h } from "vue";

import { formatNumber, formatTime } from "../../lib/formatters";

import { Button } from "@/components/ui/button";
import type { FlattenedLlmUsage } from "~~/server/lib/admin";

export const createLlmUsageColumns = (): ColumnDef<FlattenedLlmUsage>[] => [
  // ID & Type
  {
    accessorKey: "summaryId",
    header: "ID",
    cell: ({ row }) => h("div", { class: "font-mono" }, row.original.summaryId),
  },
  {
    accessorKey: "essence",
    header: "Type",
    cell: ({ row }) => h("div", { class: "capitalize" }, row.original.essence),
  },
  {
    accessorKey: "status",
    header: "Status",
  },
  {
    accessorKey: "createdAt",
    header: ({ column }) => {
      return h(
        Button,
        {
          variant: "ghost",
          onClick: () => {
            const isAsc = column.getIsSorted() === "asc";
            column.toggleSorting(isAsc);
          },
        },
        () => ["Created", h(ArrowUpDown, { class: "ml-2 h-4 w-4" })],
      );
    },
    cell: ({ row }) => {
      const date = row.original.createdAt;
      return h("div", {}, new Date(date).toLocaleString());
    },
  },

  // Summary Stats
  {
    accessorKey: "summaryModel",
    header: "Summary Model",
  },
  {
    accessorKey: "summaryTotalTokens",
    header: "Summary Tokens",
    cell: ({ row }) => formatNumber(row.original.summaryTotalTokens),
  },
  {
    accessorKey: "summaryTimeMs",
    header: "Summary Time",
    cell: ({ row }) => formatTime(row.original.summaryTimeMs),
  },

