  {
    accessorKey: "classifierModel",
    header: "Classifier Model",
    cell: ({ row }) => {
      if (row.original.essence === "youtube" || row.original.essence === "article") {
        return row.original.classifierModel || "N/A";
      }
      return "N/A";
    },
