    accessorKey: "classifierTotalTokens",
    header: "Classifier Tokens",
    cell: ({ row }) => {
      if (row.original.essence === "youtube" || row.original.essence === "article") {
        return formatNumber(row.original.classifierTotalTokens);
      }
      return "N/A";
    },
  },
  {
    accessorKey: "classifierTimeMs",
    header: "Classifier Time",
    cell: ({ row }) => {
      if (row.original.essence === "youtube" || row.original.essence === "article") {
        return formatTime(row.original.classifierTimeMs);
      }
      return "N/A";
    },
  },

  // Transcript Stats (YouTube only)
  {
    accessorKey: "transcriptModel",
    header: "Transcript Model",
    cell: ({ row }) => {
      if (row.original.essence === "youtube") {
        return row.original.transcriptModel || "N/A";
      }
      return "N/A";
    },
  },
  {
    accessorKey: "transcriptTotalTokens",
    header: "Transcript Tokens",
    cell: ({ row }) => {
      if (row.original.essence === "youtube") {
        return formatNumber(row.original.transcriptTotalTokens);
      }
      return "N/A";
    },
  },
  {
    accessorKey: "transcriptTimeMs",
    header: "Transcript Time",
    cell: ({ row }) => {
      if (row.original.essence === "youtube") {
        return formatTime(row.original.transcriptTimeMs);
      }
      return "N/A";
